const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const prose=s=>esc(s).replace(/`([^`]+)`/g,'<code>$1</code>');
const paragraphs=xs=>(Array.isArray(xs)?xs:[xs]).map(x=>`<p>${prose(x)}</p>`).join('');
const stages=['准备 · 环境与学习方式','第一阶段 · 手写基础','第二阶段 · 核心能力','第三阶段 · 项目与面试'];
let blocks=[],observer;
function highlight(text,lang){if(lang!=='python')return esc(text);return text.split('\n').map(line=>{const parts=line.match(/(?:#[^\n]*|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b(?:async|await|def|class|return|if|else|elif|for|in|from|import|with|as|try|except|raise|finally|True|False|None|and|or|not|while|break|continue|yield|assert)\b|[^#"']+?)/g)||[];return parts.map(t=>t.startsWith('#')?`<span class="comment">${esc(t)}</span>`:/^["']/.test(t)?`<span class="str">${esc(t)}</span>`:/^(async|await|def|class|return|if|else|elif|for|in|from|import|with|as|try|except|raise|finally|True|False|None|and|or|not|while|break|continue|yield|assert)$/.test(t)?`<span class="kw">${esc(t)}</span>`:esc(t)).join('')}).join('\n')}
function code(b){const n=blocks.push(b.code)-1;return `${b.description?`<p class="code-description">${prose(b.description)}</p>`:''}<div class="code-block"><div class="code-head"><span>${esc(b.file)}${b.path?`<a class="code-link" href="${esc(b.path)}" download>下载文件 ↗</a>`:''}</span><button class="copy" data-copy="${n}" aria-label="复制 ${esc(b.file)}">复制代码</button></div><pre><code>${highlight(b.code,b.lang||'python')}</code></pre></div>`}
function section(id,n,title,body){return `<section class="lesson-section" id="${id}"><div class="section-head"><span class="index">${n}</span><h2>${title}</h2></div>${body}</section>`}
function conceptDiagram(d){if(!d)return '';return `<figure class="concept-figure"><div class="figure-heading"><span class="figure-kicker">图解</span><strong>${esc(d.title)}</strong><a href="${esc(d.src)}" target="_blank" rel="noopener noreferrer" aria-label="放大查看：${esc(d.title)}">放大查看 ↗</a></div><div class="figure-scroll" tabindex="0" role="region" aria-label="${esc(d.title)}，可横向滚动"><img src="${esc(d.src)}" alt="${esc(d.alt)}" width="${d.width}" height="${d.height}" loading="lazy" decoding="async"></div><figcaption><p>${prose(d.caption)}</p><details><summary>按步骤读图</summary><ol>${d.steps.map(step=>`<li>${prose(step)}</li>`).join('')}</ol></details><span class="figure-mobile-hint">图中内容可左右滑动，也可点击放大查看。</span></figcaption></figure>`}
function lecture(w){
  const l=w.lecture;
  return `<div class="lecture-opening"><span class="lecture-label">本讲的问题</span><h3>${esc(l.question)}</h3>${paragraphs(l.opening)}</div>
    <details class="lecture-outline" open><summary>本讲阅读目录 · ${w.concepts.length} 节</summary><ol>${w.concepts.map((c,i)=>`<li><a href="#week-${w.id}/chapter-${i+1}">${esc(c.title.replace(/^\d+\s*·\s*/,''))}</a></li>`).join('')}</ol><a class="lecture-download" href="${esc(l.path)}" download>下载本周讲义 · Markdown ↗</a></details>
    ${w.concepts.map((c,i)=>`<article class="lecture-chapter" id="chapter-${i+1}"><span class="lecture-label">第 ${i+1} 节</span><h3>${esc(c.title.replace(/^\d+\s*·\s*/,''))}</h3>${paragraphs(c.body)}${paragraphs(c.discussion)}${c.example?`<div class="concept-example"><strong>案例联系：</strong>${prose(c.example)}</div>`:''}${conceptDiagram(c.diagram)}</article>`).join('')}
    <div class="lecture-lab"><h3>回到本周代码</h3><ol>${l.reading.map(x=>`<li>${prose(x)}</li>`).join('')}</ol><a class="lecture-download" href="#week-${w.id}/code">带着问题读 Python 示例 ↓</a></div>
    <div class="lecture-recap"><h3>本讲小结</h3>${paragraphs(l.recap)}<h4>换个情境，再想一遍</h4><p>${prose(l.exercise)}</p><details class="question"><summary>先独立回答，再查看参考思路</summary>${paragraphs(l.answer)}</details></div>`;
}
function renderNav(id){let stage=-1;$('#week-nav').innerHTML=COURSE.map(w=>{let label='';if(w.stage!==stage){stage=w.stage;label=`<div class="stage-label">${esc(stages[stage])}</div>`}return label+`<a href="#week-${w.id}" class="week-link ${w.id===id?'active':''}" ${w.id===id?'aria-current="page"':''}><span class="num">${String(w.id).padStart(2,'0')}</span><span>${esc(w.short)}</span></a>`}).join('');$('#week-select').innerHTML='<option value="overview">路线总览</option>'+COURSE.map(w=>`<option value="week-${w.id}">${w.id?'第 '+w.id+' 周':'开始之前'} · ${esc(w.short)}</option>`).join('');$('#week-select').value=id===-1?'overview':`week-${id}`}
function renderWeek(w){blocks=[];$('#breadcrumb').textContent=stages[w.stage];document.title=`${w.id?'第 '+w.id+' 周':'开始之前'} · ${w.title} | Agent 工程实践`;const toc=[['goals','本周目标'],['concepts','本周讲义'],['code','Python 实例'],['schedule','每天怎么学'],['practice','动手任务'],['acceptance','验收标准'],['pitfalls','常见问题'],['questions','理解检查'],['references','延伸阅读']];$('#toc-nav').innerHTML=toc.map(([id,t])=>`<a href="#week-${w.id}/${id}" data-section="${id}">${t}</a>`).join('');$('#main').innerHTML=`<div class="eyebrow">${w.id?'WEEK '+String(w.id).padStart(2,'0')+' / 12':'BEFORE YOU BUILD'}</div><h1>${esc(w.title)}</h1><p class="lead">${prose(w.intro)}</p><div class="meta"><span><em>${esc(w.hours)}</em> 建议投入</span><span>${esc(w.level)}</span><span>${w.concepts.length} 节讲义 · ${w.examples.filter(x=>(x.lang||'python')==='python').length} 个 Python 文件</span></div><div class="week-track" aria-label="12 周位置">${COURSE.filter(x=>x.id).map(x=>`<a href="#week-${x.id}" class="${x.id===w.id?'current':''}" title="第 ${x.id} 周：${esc(x.title)}" aria-label="前往第 ${x.id} 周"></a>`).join('')}</div><div class="track-label"><span>FOUNDATIONS</span><span>BUILD & EVALUATE</span><span>SHIP</span></div><section id="goals" class="objective-box"><h2>${w.id?'这一周，你要做到':'开始前，确认这几件事'}</h2><ul>${w.goals.map(x=>`<li>${prose(x)}</li>`).join('')}</ul><div class="deliverable"><strong>本周产出 / </strong>${prose(w.deliverable)}</div></section>${w.prereq?`<div class="note"><strong>先修要求：</strong>${prose(w.prereq)}</div>`:''}${section('concepts','01','本周讲义',lecture(w))}${section('code','02','从讲义到 Python 实践',`<div class="run-info"><strong>运行前准备</strong>${paragraphs(w.setup)}</div>${w.examples.map(code).join('')}<div class="run-info"><strong>运行命令</strong>${code({file:'Terminal',lang:'bash',code:w.command})}<strong>预期现象</strong><div class="expected">${esc(w.expected)}</div></div><h3>沿着执行顺序读代码</h3><ol class="walkthrough">${w.walkthrough.map(x=>`<li>${prose(x)}</li>`).join('')}</ol><div class="note">${prose(w.limit)}</div><a class="download-link" href="examples/week-${String(w.id).padStart(2,'0')}.zip" download>下载${w.id?'本周':'准备阶段'}代码与运行说明 ↗</a>`)}${section('schedule','03','每天怎么学',`<p class="code-description">按顺序完成，每天留出时间独立复现。时间不足可以顺延，验收标准不变。</p><div class="days">${w.days.map((d,i)=>`<div class="day"><span class="day-num">DAY ${String(i+1).padStart(2,'0')}</span><div><strong>${esc(d[0])}</strong><p>${prose(d[1])}</p></div></div>`).join('')}</div>`)}${section('practice','04','动手任务',`<div class="task-box"><strong>${esc(w.task.title)}</strong>${paragraphs(w.task.body)}</div>`)}${section('acceptance','05','本周验收',`<p class="code-description">这些是你需要提交的证据，读完页面不等于已经掌握。</p><ul class="criteria">${w.criteria.map(x=>`<li>${prose(x)}</li>`).join('')}</ul>`)}${section('pitfalls','06','先避开这些坑',w.pitfalls.map(p=>`<div class="mistake"><b>${esc(p[0])}</b><p>${prose(p[1])}</p></div>`).join(''))}${section('questions','07','试着解释给别人听',w.questions.map(q=>`<details class="question"><summary>${esc(q[0])}</summary>${paragraphs(q[1])}</details>`).join(''))}${section('references','08','继续深入',`<div class="refs">${w.refs.map(r=>`<a href="${esc(r[1])}" target="_blank" rel="noopener noreferrer">${esc(r[0])} ↗</a>`).join('')}</div><p class="source-note">接口参考官方文档；课程中的任务、案例和验收标准为教学设计。依赖版本与验证范围见「开始之前」。</p>`)}<div class="week-pagination">${w.id>0?`<a href="#week-${w.id-1}"><small>← 上一课</small><strong>${esc(COURSE.find(x=>x.id===w.id-1).short)}</strong></a>`:'<a href="#overview"><small>回到</small><strong>路线总览</strong></a>'}${w.id<12?`<a href="#week-${w.id+1}"><small>下一课 →</small><strong>${esc(COURSE.find(x=>x.id===w.id+1).short)}</strong></a>`:'<a href="#overview"><small>回顾你的学习</small><strong>12 周路线总览 →</strong></a>'}</div>`;observeSections()}
function overview(){blocks=[];$('#breadcrumb').textContent='12 周路线总览';document.title='12 周路线总览 | Agent 工程实践';$('#toc-nav').innerHTML='<a href="#overview">路线总览</a><a href="#week-0">开始之前</a><a href="#week-1">第 1 周</a>';$('#main').innerHTML=`<div class="eyebrow">YOUR 12-WEEK LEARNING PATH</div><h1>把 Agent 一周一周做出来。</h1><p class="lead">从亲手写下第一个循环，到拿出有证据、有边界、能复现的工程作品。每周围绕一个问题，读原理、跑代码、做实验、完成验收。</p><div class="objective-box"><h2>贯穿项目：故障排查助手</h2><p>输入故障现象，查询日志、检索文档、验证假设，最后给出带来源的结论。证据不足就说明缺口；执行失败就留下可复现的轨迹。</p><div class="diagram"><span>问题与约束</span><i>→</i><span>查询与检索</span><i>→</i><span>证据判断</span><i>→</i><span>结论或转人工</span></div><a class="download-link" href="#week-0">先检查运行环境 →</a></div><h2 class="intro-title">三段旅程，十二次可验证的进步</h2><p>示例分为离线练习与真实模型接入。先用固定数据理解机制，再用真实模型检验决策。网页提供阅读、复制和下载；Python 代码在你的本地环境运行。</p><div class="overview-grid">${COURSE.filter(w=>w.id).map(w=>`<a class="overview-card" href="#week-${w.id}"><span>WEEK ${String(w.id).padStart(2,'0')} · ${w.hours}</span><h3>${esc(w.title)}</h3><p>${esc(w.deliverable)}</p></a>`).join('')}</div><div class="note"><strong>按验收推进：</strong>不要求机械地在 84 天内结束。熟悉的后端知识可以加速；卡住时保留失败样本，修复后再前进。12 周完成一套可讲清楚的作品，不以学习时长承诺岗位或“专家”水平。</div><a class="download-link" href="examples.zip" download>下载完整 Python 示例包 ↗</a><p class="source-note">完整包包含各周 Python 文件、配套依赖、README 与测试入口。模型密钥只在本地配置，网页不接收密钥。</p>`}
function observeSections(){observer?.disconnect();observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){document.querySelectorAll('#toc-nav a').forEach(a=>a.classList.toggle('active',a.dataset.section===e.target.id))}},{rootMargin:'-12% 0px -68% 0px'});document.querySelectorAll('#main section[id]').forEach(s=>observer.observe(s))}
let currentRoute='';function route(){const hash=location.hash.slice(1);if(hash==='overview'){currentRoute=hash;renderNav(-1);overview();window.scrollTo({top:0});return}const m=hash.match(/^week-(\d+)(?:\/([a-z][a-z0-9-]*))?$/);if(m||!hash){const id=m?Number(m[1]):1;const w=COURSE.find(x=>x.id===id);if(!w){location.hash='week-1';return}const base=`week-${id}`;if(currentRoute!==base){renderNav(id);renderWeek(w);currentRoute=base}if(m?.[2]){requestAnimationFrame(()=>document.getElementById(m[2])?.scrollIntoView())}else{window.scrollTo({top:0})}}else if(!currentRoute){renderNav(1);renderWeek(COURSE.find(x=>x.id===1));currentRoute='week-1';requestAnimationFrame(()=>document.getElementById(hash)?.scrollIntoView())}}
$('#week-select').addEventListener('change',e=>location.hash=e.target.value);window.addEventListener('hashchange',route);document.addEventListener('click',async e=>{const b=e.target.closest('[data-copy]');if(!b)return;const content=blocks[Number(b.dataset.copy)];try{await navigator.clipboard.writeText(content);b.textContent='已复制';$('#toast').textContent='代码已复制';$('#toast').classList.add('show');setTimeout(()=>{b.textContent='复制代码';$('#toast').classList.remove('show')},1800)}catch{const pre=b.closest('.code-block').querySelector('code');const range=document.createRange();range.selectNodeContents(pre);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);$('#toast').textContent='已选中代码，请长按或按 Ctrl/Cmd+C 复制';$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}});route();
